def route_tickets(
    tickets: list[dict],
    rules: dict[str, dict],
    escalate_after: int | None = None,
) -> list[dict]:
    result = []
    for ticket in tickets:
        if "id" not in ticket or "severity" not in ticket or "service" not in ticket:
            continue
        ticket_id = ticket["id"]
        severity = ticket["severity"]
        service = ticket["service"]
        rule = rules.get(service, rules.get("default", {}))
        queue = rule.get("queue", "")
        priority = rule.get("priority", 0)
        if severity == "critical":
            priority += 10
        elif severity == "high":
            priority += 5
        status_code = "routed"
        if escalate_after is not None:
            age_minutes = ticket.get("age_minutes")
            if age_minutes is not None and age_minutes > escalate_after:
                priority += 3
                status_code = "escalated"
        result.append({
            "id": ticket_id,
            "queue": queue,
            "priority": priority,
            "status_code": status_code,
        })
    return result

def _resolve_rule(rules: dict[str, dict], service: str) -> dict:
    return rules.get(service, rules.get("default", {}))


def _compute_priority(base_priority: int, severity: str) -> int:
    if severity == "critical":
        return base_priority + 10
    elif severity == "high":
        return base_priority + 5
    return base_priority


def _apply_escalation(
    priority: int,
    status_code: str,
    ticket: dict,
    escalate_after: int,
) -> tuple[int, str]:
    age_minutes = ticket.get("age_minutes")
    if age_minutes is not None and age_minutes > escalate_after:
        return priority + 3, "escalated"
    return priority, status_code


def _route_ticket(
    ticket: dict,
    rules: dict[str, dict],
    escalate_after: int | None,
) -> dict | None:
    if "id" not in ticket or "severity" not in ticket or "service" not in ticket:
        return None
    ticket_id = ticket["id"]
    severity = ticket["severity"]
    service = ticket["service"]
    rule = _resolve_rule(rules, service)
    queue = rule.get("queue", "")
    priority = _compute_priority(rule.get("priority", 0), severity)
    status_code = "routed"
    if escalate_after is not None:
        priority, status_code = _apply_escalation(priority, status_code, ticket, escalate_after)
    return {
        "id": ticket_id,
        "queue": queue,
        "priority": priority,
        "status_code": status_code,
    }


def route_tickets(
    tickets: list[dict],
    rules: dict[str, dict],
    escalate_after: int | None = None,
) -> list[dict]:
    result = []
    for ticket in tickets:
        routed = _route_ticket(ticket, rules, escalate_after)
        if routed is not None:
            result.append(routed)
    return result

